c.cpp:
class Solution {
public:
    long long subsequenceSumOr(vector<int>& nums) {
        unordered_set<long long> sums{0};
        for (int x : nums) {
            auto cur = sums;
            for (long long s : cur) sums.insert(s + x);
        }
        long long ans = 0;
        for (long long s : sums) ans |= s;
        return ans;
    }
};

c.java:
class Solution {
    public long subsequenceSumOr(int[] nums) {
        Set<Long> sums = new HashSet<>();
        sums.add(0L);
        for (int x : nums) {
            List<Long> cur = new ArrayList<>(sums);
            for (long s : cur) sums.add(s + x);
        }
        long ans = 0;
        for (long s : sums) ans |= s;
        return ans;
    }
}

